INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 12, 'theory', 'Quiz: heap and heapq');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 0, 'A heap is stored in a list with the root at position 0. Where are the children of node 3?', '["Positions 4 and 5", "Positions 6 and 7", "Positions 7 and 8", "Positions 8 and 9"]', 2, 'The children of node i are at positions 2i + 1 and 2i + 2: for i = 3 that is 7 and 8. The parent of node i is (i − 1) // 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 1, 'When sifting down, the element is swapped with the smaller of the two children. Why not the larger?', '["The larger one is faster", "Otherwise the smaller child would end up under a larger parent, breaking the heap property", "The code is simpler that way", "It makes no difference"]', 1, 'After the swap the new parent must be no larger than both children. We must lift the smaller one: it is no greater than its sibling or than the element being lowered.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 2, 'Why does building a heap from an array bottom-up (heapify) take O(n) rather than O(n log n)?', '["Because it uses merge sort", "Half of the nodes are leaves and need no work, and the rest sink a constant number of levels on average: the sum of heights is linear", "Because the computer compares several elements at once", "Because the heap is already sorted"]', 1, 'There are about n / 2^(h+1) nodes at height h, and each sinks at most h levels: the series n · Σ h / 2^h converges to a constant times n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 3, 'How do you get a max-heap with the heapq module?', '["Call heapq.maxheap()", "Push numbers with a minus sign and flip the sign when popping", "Sort the list in descending order", "It is impossible"]', 1, 'heapq only provides a min-heap. The minus sign reverses the order: the smallest of the negated numbers is the largest of the originals.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 4, 'You need to keep the k largest elements of a stream. Which heap, of what size?', '["A max-heap of size n", "A min-heap of size k: the root is the smallest of the k best", "A max-heap of size k", "Two heaps of size n / 2"]', 1, 'A new element is compared with the root of the min-heap: if it is larger, it pushes the root out. Result: n log k time and k memory.');
